 @Test @Order(14) void compatibleAssociationNeverChoosesAnAmbiguousOrConflictingSource()throws Exception {
  var source=auth("00001","L00566785");source.put("id","source-1");var missing=new LinkedHashMap<>(source);for(String key:List.of("sourceSystem","appId","application","tenantId"))missing.remove(key);
  var match=new FindingLinker(List.of(source),"user").match(missing);assertEquals("LINKED_WEAK",match.status());assertEquals("source-1",match.sourceId());assertEquals("AUTH_ID_PARTIAL_SCOPE",match.method());
  var wrongTenant=new LinkedHashMap<>(missing);wrongTenant.put("tenantId","OTHER");assertEquals("SCOPE_CONFLICT",new FindingLinker(List.of(source),"user").match(wrongTenant).reason());
  var caseTenant=new LinkedHashMap<>(missing);caseTenant.put("tenantId","t1");assertEquals("SCOPE_CONFLICT",new FindingLinker(List.of(source),"user").match(caseTenant).reason());
  var wrongId=new LinkedHashMap<>(missing);wrongId.put("authorizationId","NOT-FOUND");assertEquals("UNLINKED",new FindingLinker(List.of(source),"user").match(wrongId).status());
  var withoutId=new LinkedHashMap<>(missing);withoutId.remove("authorizationId");var other=new LinkedHashMap<>(source);other.putAll(map("id","source-2","appId","OTHER","application","另一个应用"));assertEquals("AMBIGUOUS",new FindingLinker(List.of(source,other),"user").match(withoutId).status());assertNull(new FindingLinker(List.of(source,other),"user").match(withoutId).sourceId());
  var wrongRole=new LinkedHashMap<>(withoutId);wrongRole.put("permissionName","另一权限");assertEquals("OBJECT_MISMATCH",new FindingLinker(List.of(source),"user").match(wrongRole).reason());
  var rawPoint=point();rawPoint.put("id","point-1");var findingPoint=new LinkedHashMap<>(rawPoint);for(String key:List.of("sourceSystem","appId","application","tenantId"))findingPoint.remove(key);assertEquals("LINKED_WEAK",new FindingLinker(List.of(rawPoint),"matrix").match(findingPoint).status());
 }
