 @Test @Order(19) void syntheticReportAtReportedScaleKeepsAllRowsAndLinks()throws Exception {
  long started=System.nanoTime();byte[] bytes;
  try(Workbook b=new org.apache.poi.xssf.streaming.SXSSFWorkbook(100);ByteArrayOutputStream out=new ByteArrayOutputStream()){
   List<Map<String,Object>> originals=new ArrayList<>(),risks=new ArrayList<>(),points=new ArrayList<>(),matrixRisks=new ArrayList<>();
   for(int i=0;i<7367;i++){var raw=auth(String.format("A%05d",i),"L"+String.format("%08d",i));originals.add(raw);if(i<284){var f=new LinkedHashMap<>(raw);for(String k:List.of("sourceSystem","appId","application","tenantId"))f.remove(k);f.putAll(map("ruleCode","1","risk","高","violation","合成用户风险原因"));risks.add(f);}}
   for(int i=0;i<17505;i++){var raw=point();raw.put("pointId",String.format("P%06d",i));points.add(raw);if(i<810){var f=new LinkedHashMap<>(raw);for(String k:List.of("sourceSystem","appId","application","tenantId"))f.remove(k);f.putAll(map("ruleCode","8a","risk","高","violation","合成矩阵风险原因"));matrixRisks.add(f);}}
   sheet(b,"AUTH",originals);sheet(b,"USER_RISK",risks);sheet(b,"POINT",points);sheet(b,"MATRIX_RISK",matrixRisks);b.write(out);bytes=out.toByteArray();
  }
  var job=upload("P12",bytes);var draft=pubs.draft(aa,str(job,"draftId"),false);assertEquals(7367,db.count("SELECT COUNT(*) FROM source_auth WHERE dataset_id=:d",map("d",draft.get("userDatasetId"))));assertEquals(17505,db.count("SELECT COUNT(*) FROM source_point WHERE dataset_id=:d",map("d",draft.get("matrixDatasetId"))));assertEquals(1094,db.count("SELECT COUNT(*) FROM risk_finding WHERE dataset_id IN (:ids) AND link_status='LINKED_WEAK'",map("ids",List.of(draft.get("userDatasetId"),draft.get("matrixDatasetId")))));assertEquals(25966,((Number)job.get("processedRows")).longValue());assertEquals(4,num(job,"completedSheets"));assertEquals("DONE",job.get("phase"));System.out.println("SYNTHETIC_REPORTED_SCALE: AUTH=7367 USER_RISK=284 POINT=17505 MATRIX_RISK=810 linked=1094/1094 seconds="+((System.nanoTime()-started)/1_000_000_000d));
 }

